addListener(() => {});\\n')\n    refs=[manifest['background'].get('service_worker')]\n    for obj,key in [(manifest.get('action',{}),'default_popup'),(manifest.get('options_ui',{}),'page')]:\n        if obj.get(key):refs.append(obj[key])\n    if manifest.get('options_page'):refs.append(manifest['options_page'])\n    refs.extend(manifest['icons'].values())\n    for content in manifest.get('content_scripts',[]):refs.extend(content.get('js',[])+content.get('css',[]))\n    for ref in refs:\n        if not isinstance(ref,str)or ref.startswith('/')or '..'in ref.split('/')or not(work/ref).is_file():raise ValueError('Manifest references a missing/unsafe file: '+str(ref))\n    (work/'manifest.json').write_text(json.dumps(manifest,indent=2))\n    if not(source/'tests/extension.test.cjs').is_file():raise ValueError('Meaningful tests/extension.test.cjs is required')\n    return manifest\n\ndef build():\n    worker.validate();root=Path(os.environ['GITHUB_WORKSPACE']);temp=Path(os.environ['RUNNER_TEMP']);out=root/'output';out.mkdir(exist_ok=True)\n    report={'project_id':os.environ['PROJECT_ID'],'request_id':os.environ['REQUEST_ID'],'source_sha':os.environ['SOURCE_SHA'],'platform':'extension','build_result':'failure','analyze_passed':False,'tests_passed':False,'signature_verified':False,'browser_smoke_passed':False,'store_published':False,'code_signing':'unpacked-extension-zip','files':[]};logs=[]\n    try:\n        source=root/'projects'/report['project_id'];work=temp/'extension-package';manifest=prepare(source,work)\n        for p in sorted(work.rglob('*')):\n            if p.suffix in {'.js','.mjs','.cjs'}:\n                r=subprocess.run(['node','--check',str(p)],capture_output=True,text=True,timeout=30);logs.append(r.stdout+r.stderr)\n                if r.returncode:raise ValueError('JavaScript syntax check failed: '+p.name)\n        report['analyze_passed']=True\n        r=subprocess.run(['node',str(root/'.builder/test_extension.cjs'),str(work),str(source/'tests/extension.test.cjs')],capture_output=True,text=True,timeout=150)\n        logs.append(r.stdout+r.stderr)\n        if r.returncode:raise ValueError('Chromium extension tests failed')\n        report['browser_smoke_passed']=True;report['tests_passed']=True\n        report['permissions']=manifest.get('permissions',[]);report['host_permissions']=manifest.get('host_permissions',[])\n        package=out/(report['project_id']+'-chrome-extension.zip')\n        with zipfile.ZipFile(package,'w',zipfile.ZIP_DEFLATED)as z:\n            for p in sorted(work.rglob('*')):\n                if p.is_file():z.write(p,p.relative_to(work))\n        with zipfile.ZipFile(package)as z:\n            if z.testzip()or'manifest.json'not in z.namelist():raise ValueError('Invalid extension ZIP')\n        report['files']=[{'name':package.name,'size_bytes':package.stat().st_size,'sha256':hashlib.sha256(package.read_bytes()).hexdigest()}];report['build_result']='success'\n    except Exception as e:report['error']=str(e);logs.append(str(e))\n    finally:\n        (out/'Build-Report.json').write_text(json.dumps(report,indent=2));(out/'build.log').write_text('\\n'.join(logs)[-120000:])\n    print('Extension result:',report['build_result'])\n    if report['build_result']!='success':raise SystemExit(1)\n\nif __name__=='__main__':build()\n", ".builder/test_extension.cjs": "const {chromium}=require('playwright');\nconst assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');\n(async()=>{\n const extension=path.resolve(process.argv[2]),testFile=path.resolve(process.argv[3]);\n const context=await chromium.launchPersistentContext('',{channel:'chromium',headless:true,args:[`--disable-extensions-except=${extension}`,`--load-extension=${extension}`]});\n context.setDefaultTimeout(15000);\n try{\n  let [worker]=context.serviceWorkers();\n  if(!worker)worker=await context.waitForEvent('serviceworker',{timeout:20000});\n  const extensionId=new URL(worker.url()).host;\n  assert.match(extensionId,/^[a-p]{32}$/);\n  const manifest=await worker.evaluate(()=>chrome.runtime.getManifest());\n  assert.equal(manifest.manifest_version,3);\n  const test=require(testFile);assert.equal(typeof test,'function','Export async function({context,extensionId,assert}) from tests/extension.test.cjs');\n  await test({context,extensionId,assert});\n  console.log('PASS: extension loaded in Chromium and project behavior tests passed.');\n }finally{await context.close();}\n})().catch(e=>{console.error(e);process.exit(1)});\n", ".builder/publish.py": "\"\"\"Publish verified packages in a separate job without executing app source.\"\"\"\nimport hashlib,json,os,re,subprocess\nfrom pathlib import Path\n\ndef verified_files(folder, platform):\n    pid=os.environ['PROJECT_ID'];request=os.environ['REQUEST_ID'];sha=os.environ['SOURCE_SHA']\n    if not re.fullmatch(r'[a-z][a-z0-9_]{1,39}',pid) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_-]{5,63}',request) or not re.fullmatch(r'[a-f0-9]{40}',sha):\n        raise ValueError('Invalid release identity')\n    report_path=folder/'Build-Report.json'\n    if report_path.is_symlink():raise ValueError('Unsafe report')\n    report=json.loads(report_path.read_text())\n    expected={'project_id':pid,'request_id':request,'source_sha':sha,'platform':platform,'build_result':'success','analyze_passed':True,'tests_passed':True}\n    if platform in {'android','ios'}:expected['signature_verified']=True\n    elif platform=='ios_unsigned':expected.update(signature_verified=False,code_signing='unsigned',requires_signing=True,install_ready=False,device_build_verified=True,package_verified=True)\n    elif platform=='windows':expected.update(installer_smoke_passed=True,runtime_smoke_passed=True,code_signing='unsigned')\n    elif platform=='extension':expected.update(browser_smoke_passed=True,code_signing='unpacked-extension-zip')\n    else:raise ValueError('Unsupported release platform')\n    if any(report.get(k)!=v for k,v in expected.items()):raise ValueError('Build report does not match this successful signed build')\n    names={'android':[pid+'-android.apk'],'ios':[pid+'-ios.ipa'],'ios_unsigned':[pid+'-ios-unsigned.ipa'],'windows':[pid+'-windows-setup.exe',pid+'-windows-portable.zip'],'extension':[pid+'-chrome-extension.zip']}[platform]\n    actual=[];packages=[]\n    for name in names:\n        package=folder/name\n        if package.is_symlink() or not package.is_file():raise ValueError('Missing or unsafe package')\n        digest=hashlib.sha256(package.read_bytes()).hexdigest()\n        actual.append({'name':name,'size_bytes':package.stat().st_size,'sha256':digest});packages.append(package)\n    if report.get('files')!=actual:raise ValueError('Package hash or size differs from build report')\n    checksum=folder/'SHA256SUMS.txt';checksum.write_text(''.join(f['sha256']+'  '+f['name']+'\\n'for f in actual))\n    return [*packages,report_path,checksum]\n\ndef main():\n    repo=os.environ['GITHUB_REPOSITORY']\n    if not re.fullmatch(r'[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+',repo):raise ValueError('Invalid repository')\n    for platform in ['android','ios','ios_unsigned','windows','extension']:\n        folder=Path('release-input')/platform\n        if not folder.is_dir():continue\n        files=verified_files(folder,platform)\n        tag='builds/'+os.environ['PROJECT_ID']+'/'+os.environ['REQUEST_ID']+'/'+platform\n        notes=folder/'release-notes.txt'\n        verification={'android':'Android signature verified. No physical phone tested.','ios':'Apple signature verified. Installation requires the matching registered iPhone and unexpired profile. No physical phone tested.','ios_unsigned':'UNSIGNED iPhone device IPA. arm64 device bundle and Payload structure verified. MUST SIGN BEFORE INSTALLATION. No signing credentials or device ID were used. Upload to your compatible signing service, such as https://www.ipasigner.com/, then install the signed result. No physical phone tested.','windows':'Installer deployment and app launch smoke tests passed on CI. Executables are unsigned; Windows may show an unknown-publisher warning.','extension':'Loaded in Chromium and behavior tests passed. ZIP requires extraction and Load unpacked, or separate Web Store review. No store publication performed.'}[platform]\n        notes.write_text('Built from '+os.environ['SOURCE_SHA']+'. Analysis and tests passed. '+verification+'\\n\\nDownloads have no automatic Actions artifact expiry. Availability depends on the repository and GitHub.\\n')\n        common=['--repo',repo]\n        subprocess.run(['gh','release','create',tag,*map(str,files),*common,'--draft','--target',os.environ['SOURCE_SHA'],'--title',os.environ['PROJECT_ID']+' / '+platform+' / '+os.environ['REQUEST_ID'],'--notes-file',str(notes),'--latest=false'],check=True)\n        subprocess.run(['gh','release','edit',tag,*common,'--draft=false','--latest=false'],check=True)\n        with open(os.environ['GITHUB_STEP_SUMMARY'],'a')as summary:\n            summary.write('Verified '+platform+' download: https://github.com/'+repo+'/releases/tag/'+tag+'\\n')\n\nif __name__=='__main__':main()\n", ".github/workflows/mobile-builder.yml": "name: Universal App Builder\nrun-name: Universal Builder / ${{ inputs.project_id }} / ${{ inputs.request_id }}\non:\n  workflow_dispatch:\n    inputs:\n      project_id: {description: Project ID, required: true, type: string}\n      platform: {description: Platform, required: true, type: choice, options: [android, ios, both, windows, extension, ios_unsigned]}\n      request_id: {description: Unique request ID, required: true, type: string}\n      source_sha: {description: Exact source commit, required: true, type: string}\npermissions:\n  contents: read\nconcurrency:\n  group: mobile-builder-${{ inputs.project_id }}-${{ inputs.request_id }}\n  cancel-in-progress: false\nenv:\n  PYTHONUTF8: '1'\n  PYTHONIOENCODING: utf-8\n  PROJECT_ID: ${{ inputs.project_id }}\n  PLATFORM: ${{ inputs.platform }}\n  REQUEST_ID: ${{ inputs.request_id }}\n  SOURCE_SHA: ${{ inputs.source_sha }}\njobs:\n  readiness:\n    name: Check signing readiness\n    runs-on: ubuntu-latest\n    timeout-minutes: 5\n    outputs:\n      android: ${{ steps.check.outputs.android }}\n      ios: ${{ steps.check.outputs.ios }}\n      windows: ${{ steps.check.outputs.windows }}\n      extension: ${{ steps.check.outputs.extension }}\n      ios_unsigned: ${{ steps.check.outputs.ios_unsigned }}\n    steps:\n      - uses: actions/checkout@v4\n        with: {ref: '${{ inputs.source_sha }}', persist-credentials: false}\n      - id: check\n        run: python3 .builder/build.py readiness\n        env:\n          HAS_ANDROID_KEYSTORE_BASE64: ${{ secrets.ANDROID_KEYSTORE_BASE64 != '' }}\n          HAS_ANDROID_KEYSTORE_PASSWORD: ${{ secrets.ANDROID_KEYSTORE_PASSWORD != '' }}\n          HAS_ANDROID_KEY_ALIAS: ${{ secrets.ANDROID_KEY_ALIAS != '' }}\n          HAS_ANDROID_KEY_PASSWORD: ${{ secrets.ANDROID_KEY_PASSWORD != '' }}\n          HAS_APPLE_CERTIFICATE_P12_BASE64: ${{ secrets.APPLE_CERTIFICATE_P12_BASE64 != '' }}\n          HAS_APPLE_CERTIFICATE_PASSWORD: ${{ secrets.APPLE_CERTIFICATE_PASSWORD != '' }}\n          HAS_APPLE_PROVISIONING_PROFILE_BASE64: ${{ secrets.APPLE_PROVISIONING_PROFILE_BASE64 != '' }}\n          HAS_APPLE_TEAM_ID: ${{ secrets.APPLE_TEAM_ID != '' }}\n      - uses: actions/upload-artifact@v4\n        with:\n          name: Build-Readiness-${{ inputs.request_id }}\n          path: readiness/Build-Readiness.json\n          retention-days: 14\n  publish:\n    name: Preserve verified app downloads\n    needs: [android, ios, ios_unsigned, windows, extension]\n    if: always() && (needs.android.result == 'success' || needs.ios.result == 'success' || needs.ios_unsigned.result == 'success' || needs.windows.result == 'success' || needs.extension.result == 'success')\n    runs-on: ubuntu-latest\n    timeout-minutes: 5\n    permissions:\n      contents: write\n      actions: read\n    steps:\n      - uses: actions/checkout@v4\n        with: {persist-credentials: false}\n      - uses: actions/download-artifact@v4\n        if: needs.android.result == 'success'\n        with:\n          name: Android-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: release-input/android\n      - uses: actions/download-artifact@v4\n        if: needs.ios.result == 'success'\n        with:\n          name: iOS-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: release-input/ios\n      - uses: actions/download-artifact@v4\n        if: needs.windows.result == 'success'\n        with:\n          name: Windows-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: release-input/windows\n      - uses: actions/download-artifact@v4\n        if: needs.extension.result == 'success'\n        with:\n          name: Extension-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: release-input/extension\n      - uses: actions/download-artifact@v4\n        if: needs.ios_unsigned.result == 'success'\n        with:\n          name: iOS-Unsigned-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: release-input/ios_unsigned\n      - name: Publish hash-checked packages and reports\n        run: python3 .builder/publish.py\n        env:\n          GH_TOKEN: ${{ github.token }}\n  ios_unsigned:\n    name: Unsigned iPhone device IPA - sign before install\n    needs: readiness\n    if: needs.readiness.outputs.ios_unsigned == 'true'\n    runs-on: macos-latest\n    timeout-minutes: 35\n    steps:\n      - uses: actions/checkout@v4\n        with: {ref: '${{ inputs.source_sha }}', persist-credentials: false}\n      - name: Install Flutter stable\n        run: |\n          git clone --depth 1 --branch stable https://github.com/flutter/flutter.git \"$RUNNER_TEMP/flutter\"\n          echo \"$RUNNER_TEMP/flutter/bin\" >> \"$GITHUB_PATH\"\n      - name: Analyze, test and export unsigned device IPA\n        run: python3 .builder/ios_unsigned.py\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: iOS-Unsigned-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: output/\n          if-no-files-found: error\n          retention-days: 14\n  android:\n    name: Android signed APK\n    needs: readiness\n    if: needs.readiness.outputs.android == 'true'\n    runs-on: ubuntu-latest\n    timeout-minutes: 30\n    steps:\n      - uses: actions/checkout@v4\n        with: {ref: '${{ inputs.source_sha }}', persist-credentials: false}\n      - uses: actions/setup-java@v4\n        with: {distribution: temurin, java-version: '17'}\n      - name: Install Flutter stable\n        run: |\n          git clone --depth 1 --branch stable https://github.com/flutter/flutter.git \"$RUNNER_TEMP/flutter\"\n          echo \"$RUNNER_TEMP/flutter/bin\" >> \"$GITHUB_PATH\"\n      - name: Analyze, test, build and verify signed APK\n        run: python3 .builder/build.py android\n        env:\n          ANDROID_KEYSTORE_BASE64: ${{ secrets.ANDROID_KEYSTORE_BASE64 }}\n          ANDROID_KEYSTORE_PASSWORD: ${{ secrets.ANDROID_KEYSTORE_PASSWORD }}\n          ANDROID_KEY_ALIAS: ${{ secrets.ANDROID_KEY_ALIAS }}\n          ANDROID_KEY_PASSWORD: ${{ secrets.ANDROID_KEY_PASSWORD }}\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: Android-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: output/\n          if-no-files-found: error\n          retention-days: 14\n  ios:\n    name: iOS signed IPA\n    needs: readiness\n    if: needs.readiness.outputs.ios == 'true'\n    runs-on: macos-latest\n    timeout-minutes: 40\n    steps:\n      - uses: actions/checkout@v4\n        with: {ref: '${{ inputs.source_sha }}', persist-credentials: false}\n      - name: Install Flutter stable\n        run: |\n          git clone --depth 1 --branch stable https://github.com/flutter/flutter.git \"$RUNNER_TEMP/flutter\"\n          echo \"$RUNNER_TEMP/flutter/bin\" >> \"$GITHUB_PATH\"\n      - name: Analyze, test, build and verify signed IPA\n        run: python3 .builder/build.py ios\n        env:\n          APPLE_CERTIFICATE_P12_BASE64: ${{ secrets.APPLE_CERTIFICATE_P12_BASE64 }}\n          APPLE_CERTIFICATE_PASSWORD: ${{ secrets.APPLE_CERTIFICATE_PASSWORD }}\n          APPLE_PROVISIONING_PROFILE_BASE64: ${{ secrets.APPLE_PROVISIONING_PROFILE_BASE64 }}\n          APPLE_TEAM_ID: ${{ secrets.APPLE_TEAM_ID }}\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: iOS-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: output/\n          if-no-files-found: error\n          retention-days: 14\n  windows:\n    name: Windows installer and portable app\n    needs: readiness\n    if: needs.readiness.outputs.windows == 'true'\n    runs-on: windows-2022\n    timeout-minutes: 35\n    steps:\n      - uses: actions/checkout@v4\n        with: {ref: '${{ inputs.source_sha }}', persist-credentials: false}\n      - name: Install Flutter stable\n        shell: pwsh\n        run: |\n          git clone --depth 1 --branch stable https://github.com/flutter/flutter.git \"$env:RUNNER_TEMP/flutter\"\n          if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }\n          \"$env:RUNNER_TEMP/flutter/bin\" | Out-File -FilePath $env:GITHUB_PATH -Encoding utf8 -Append\n      - name: Analyze, test, build, install and launch\n        run: python .builder/windows.py\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: Windows-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: output/\n          if-no-files-found: error\n          retention-days: 14\n  extension:\n    name: Chrome extension package and Chromium tests\n    needs: readiness\n    if: needs.readiness.outputs.extension == 'true'\n    runs-on: ubuntu-latest\n    timeout-minutes: 12\n    steps:\n      - uses: actions/checkout@v4\n        with: {ref: '${{ inputs.source_sha }}', persist-credentials: false}\n      - uses: actions/setup-node@v4\n        with: {node-version: '22'}\n      - name: Install pinned Chromium test tools\n        run: |\n          npm install --prefix \"$RUNNER_TEMP/extension-tools\" playwright@1.56.1 --no-audit --no-fund\n          \"$RUNNER_TEMP/extension-tools/node_modules/.bin/playwright\" install --with-deps chromium\n          echo \"NODE_PATH=$RUNNER_TEMP/extension-tools/node_modules\" >> \"$GITHUB_ENV\"\n      - name: Validate, test and package extension\n        run: python3 .builder/extension.py\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: Extension-${{ inputs.project_id }}-${{ inputs.request_id }}\n          path: output/\n          if-no-files-found: error\n          retention-days: 14\n"};

function mb_context(settings={}) {
 const owner=String(settings.githubOwner||'').trim(),repo=String(settings.githubRepo||'').trim(),token=String(settings.githubToken||'').trim(),branch=String(settings.githubBranch||'main').trim();
 if(!/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(owner)||!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,99}$/.test(repo))throw new Error('Choose your GitHub owner and dedicated builder repository in Settings.');
 if(!token)throw new Error('Enter a repository-scoped GitHub token in the plugin password setting, never in chat.');
 if(!/^[A-Za-z0-9][A-Za-z0-9_/.-]{0,99}$/.test(branch)||branch.includes('..')||branch.includes('//'))throw new Error('Invalid branch.');
 const base='/repos/'+owner+'/'+repo,web='https://github.com/'+owner+'/'+repo;
 const cap=(['32','64','128'].includes(String(settings.maxDownloadMB))?Number(settings.maxDownloadMB):64)*1048576;
 const clean=s=>String(s).split(token).join('[REDACTED]').replace(/(?:github_pat_|gh[pousr]_)[A-Za-z0-9_]+/g,'[REDACTED]');
 async function api(path,method='GET',data,binary=false){
  if(path!==base&&!path.startsWith(base+'/'))throw new Error('Request outside the configured repository refused.');
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),40000);
  try{
   const r=await fetch('https://api.github.com'+path,{method,headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+token,'X-GitHub-Api-Version':'2022-11-28',...(data?{'Content-Type':'application/json'}:{})},...(data?{body:JSON.stringify(data)}:{}),credentials:'omit',redirect:binary?'follow':'error',signal:controller.signal});
   if(!r.ok){let message='';try{message=(await r.json()).message||'';}catch(_){}const e=new Error(clean('GitHub '+r.status+': '+message).slice(0,800));e.status=r.status;throw e;}
   if(binary){
    if(Number(r.headers.get('content-length')||0)>cap)throw new Error('Artifact exceeds download limit.');
    const reader=r.body.getReader(),chunks=[];let size=0;
    try{while(true){const v=await reader.read();if(v.done)break;size+=v.value.length;if(size>cap){await reader.cancel();throw new Error('Artifact exceeds download limit.');}chunks.push(v.value);}}finally{reader.releaseLock();}
    const result=new Uint8Array(size);let offset=0;for(const part of chunks){result.set(part,offset);offset+=part.length;}return result;
   }
   if(r.status===204)return null;const text=await r.text();return text?JSON.parse(text):null;
  }catch(e){if(e.name==='AbortError')throw new Error('Request timed out; a write or build may have completed. Check status before retrying.');throw e;}
  finally{clearTimeout(timer);}
 }
 return{owner,repo,branch,base,web,cap,clean,api,allowPublic:settings.allowPublicSource==='on'};
}
function mb_id(value){if(typeof value!=='string'||!/^[a-z][a-z0-9_]{1,39}$/.test(value))throw new Error('Project ID must start with a lowercase letter and contain 2–40 lowercase letters, digits or underscores.');return value;}
function mb_path(path){if(typeof path!=='string'||path.length>200||path.includes('\\')||path.includes('\0')||path.split('/').some(x=>!x||x==='.'||x==='..')||!/^(lib\/|test\/|assets\/|pubspec\.yaml$|analysis_options\.yaml$|README\.md$)/.test(path)||/\.(?:p12|pfx|jks|keystore|mobileprovision|pem|key)$/i.test(path))throw new Error('Use safe Flutter lib/, test/, assets/ text paths or supported project-root files. No signing files.');return path;}
function mb_text(value){return new TextDecoder().decode(Uint8Array.from(atob(value.replace(/\s/g,'')),c=>c.charCodeAt(0)));}
function mb_json(value){return JSON.stringify(value,null,2);}
async function mb_repository(c){const r=await c.api(c.base);if(!r.private&&!c.allowPublic)throw new Error('Public source is disabled. Enable Allow public app source only if you want source, logs and build artifacts to be publicly accessible.');if(r.full_name&&r.full_name.toLowerCase()!==(c.owner+'/'+c.repo).toLowerCase())throw new Error('Repository identity differs from the configured owner/name.');return r;}
async function mb_head(c){const r=await c.api(c.base+'/git/ref/heads/'+c.branch.split('/').map(encodeURIComponent).join('/'));const commit=await c.api(c.base+'/git/commits/'+r.object.sha);return{sha:r.object.sha,tree:commit.tree.sha};}
async function mb_file(c,path,ref){return c.api(c.base+'/contents/'+path.split('/').map(encodeURIComponent).join('/')+'?ref='+encodeURIComponent(ref));}
async function mb_commit(c,head,files,message){
 const tree=await c.api(c.base+'/git/trees','POST',{base_tree:head.tree,tree:files.map(f=>({path:f.path,mode:'100644',type:'blob',content:f.content}))});
 const commit=await c.api(c.base+'/git/commits','POST',{message,tree:tree.sha,parents:[head.sha]});
 await c.api(c.base+'/git/refs/heads/'+c.branch.split('/').map(encodeURIComponent).join('/'),'PATCH',{sha:commit.sha,force:false});return commit.sha;
}
function mobile_builder_setup_status(params,settings={}){
 let deflate=false;try{new DecompressionStream('deflate-raw');deflate=true;}catch(_){}
 return mb_json({plugin:'Universal App Builder',modes:['android','ios','ios_unsigned','windows','extension'],token_configured:!!String(settings.githubToken||'').trim(),owner_configured:!!settings.githubOwner,repository_configured:!!settings.githubRepo,browser_artifact_extraction_supported:deflate,public_source_enabled:settings.allowPublicSource==='on',connection_verified:false,
  required:'A dedicated GitHub repository initialized with a README; repository-scoped Contents/Actions read-write access, plus Workflows write for pipeline installation.',
  signing:'Persistent Android release signing secrets; Apple Distribution certificate plus a matching unexpired ad hoc provisioning profile covering the target iPhone.',
  note:'Offline check only. ChatGPT GitHub access is separate from TypingMind. No native compilation or live build has been verified by this check. Never paste credentials in chat.'});
}
async function mobile_builder_connect(params,settings){
 const c=mb_context(settings),r=await mb_repository(c);let installed=true;const mismatches=[];
 for(const[path,content]of Object.entries(MB_BACKEND)){try{const f=await mb_file(c,path,c.branch);if(mb_text(f.content)!==content){installed=false;mismatches.push(path);}}catch(e){if(e.status===404){installed=false;mismatches.push(path);}else throw e;}}
 return mb_json({status:'connected',repository:r.full_name,visibility:r.private?'private':'public',pipeline_verified:installed,pipeline_mismatches:mismatches,modes:['android','ios','ios_unsigned','windows','extension'],url:c.web,signing_readiness:'Checked by workflow presence checks and actual signing validation. Secret values are never read by this plugin.'});
}
async function mobile_builder_install_pipeline(params,settings){
 const c=mb_context(settings);await mb_repository(c);const head=await mb_head(c),files=[];
 if(params.expected_commit&&params.expected_commit!==head.sha)throw new Error('Branch changed. Read the latest state first.');
 for(const [path,content]of Object.entries(MB_BACKEND)){
  try{const f=await mb_file(c,path,head.sha);if(mb_text(f.content)!==content)throw new Error('Existing builder file differs; review it before replacement: '+path);}
  catch(e){if(e.status===404)files.push({path,content});else throw e;}
 }
 const sha=files.length?await mb_commit(c,head,files,'Install TypingMind Mobile App Builder'):head.sha;
 return mb_json({status:files.length?'installed':'already_installed',commit:sha,build_started:false,url:c.web+'/actions'});
}
async function mobile_builder_save_project(params,settings){
 const c=mb_context(settings),id=mb_id(params.project_id);
 if(typeof params.app_name!=='string'||!params.app_name.trim()||params.app_name.length>80||/[\x00-\x1f]/.test(params.app_name))throw new Error('Provide an app name of 1–80 characters.');
 if(!/^[A-Za-z][A-Za-z0-9_]*(?:\.[A-Za-z][A-Za-z0-9_]*){2,}$/.test(params.bundle_id||'')||params.bundle_id.length>150)throw new Error('Use an app identifier such as com.worldgate.shipments.');
 if(!Array.isArray(params.files)||!params.files.length||params.files.length>40)throw new Error('Save 1–40 source files at a time.');
 const seen=new Set();let total=0;
 const files=params.files.map(f=>{const path=mb_path(f.path);if(seen.has(path))throw new Error('Duplicate file path.');seen.add(path);
  if(typeof f.content!=='string')throw new Error('Source content must be UTF-8 text.');const size=new TextEncoder().encode(f.content).length;total+=size;if(size>262144)throw new Error('Source file exceeds 256 KiB.');
  if(/github_pat_|ghp_|sk-[a-fA-F0-9]{24,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/.test(f.content))throw new Error('Potential credential detected. Use secrets/configuration, not source.');
